package syntax

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"testing"
)

// Fixtures generated by the Lua parser (tests/gen_ast.lua):
//
//	tests/fixtures/ast/<dir>/<name>.json  <-  tests/fixtures/<dir>/<name>.zortex
const fixtures = "../../tests/fixtures"

type pair struct{ name, source, ast string }

func fixturePairs(t *testing.T) []pair {
	t.Helper()
	var out []pair
	root := filepath.Join(fixtures, "ast")
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() || !strings.HasSuffix(path, ".json") {
			return err
		}
		rel, _ := filepath.Rel(root, path)
		name := strings.TrimSuffix(rel, ".json")
		out = append(out, pair{name, filepath.Join(fixtures, name+".zortex"), path})
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].name < out[j].name })
	if len(out) < 6 {
		t.Fatalf("expected the AST fixtures, found %d in %s", len(out), root)
	}
	return out
}

func decode(t *testing.T, data []byte) any {
	t.Helper()
	var v any
	if err := json.Unmarshal(data, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

// firstDiff describes where two decoded JSON values first differ.
func firstDiff(path string, want, got any) string {
	switch w := want.(type) {
	case map[string]any:
		g, ok := got.(map[string]any)
		if !ok {
			return fmt.Sprintf("%s: want object, got %v", path, got)
		}
		keys := map[string]bool{}
		for k := range w {
			keys[k] = true
		}
		for k := range g {
			keys[k] = true
		}
		sorted := make([]string, 0, len(keys))
		for k := range keys {
			sorted = append(sorted, k)
		}
		sort.Strings(sorted)
		for _, k := range sorted {
			if d := firstDiff(path+"."+k, w[k], g[k]); d != "" {
				return d
			}
		}
	case []any:
		g, ok := got.([]any)
		if !ok {
			return fmt.Sprintf("%s: want array, got %v", path, got)
		}
		for i := 0; i < len(w) || i < len(g); i++ {
			if i >= len(w) || i >= len(g) {
				return fmt.Sprintf("%s: want %d items, got %d", path, len(w), len(g))
			}
			if d := firstDiff(fmt.Sprintf("%s[%d]", path, i), w[i], g[i]); d != "" {
				return d
			}
		}
	default:
		if !reflect.DeepEqual(want, got) {
			return fmt.Sprintf("%s: want %v, got %v", path, want, got)
		}
	}
	return ""
}

func TestConformance(t *testing.T) {
	for _, p := range fixturePairs(t) {
		t.Run(p.name, func(t *testing.T) {
			src, err := os.ReadFile(p.source)
			if err != nil {
				t.Fatal(err)
			}
			expected, err := os.ReadFile(p.ast)
			if err != nil {
				t.Fatal(err)
			}
			got, err := json.Marshal(Parse(SplitLines(string(src)), true))
			if err != nil {
				t.Fatal(err)
			}
			if d := firstDiff("ast", decode(t, expected), decode(t, got)); d != "" {
				lines := SplitLines(string(src))
				var lnum int
				if _, err := fmt.Sscanf(d, "ast.lines[%d]", &lnum); err == nil && lnum < len(lines) {
					d += fmt.Sprintf("\n  line %d: %q", lnum+1, lines[lnum])
				}
				t.Fatal(d)
			}
		})
	}
}

func TestHelpers(t *testing.T) {
	if got := StripAttributes("1.4 - zortex @p1 @size(lg) me@example.com"); got != "1.4 - zortex me@example.com" {
		t.Errorf("StripAttributes: %q", got)
	}
	it := ItemOf("- KR1: [ ] Key result [P/#1 Programming]")
	if it == nil || it.Key != "KR1" || it.Mark != " " || *it.MarkCol != 7 || it.ContentCol != 11 {
		t.Errorf("ItemOf KR: %+v", it)
	}
	if it := ItemOf("16:00 - 17:00 Ranged"); it == nil || it.Time.From != "16:00" || it.Time.To != "17:00" || it.ContentCol != 14 {
		t.Errorf("ItemOf time range: %+v", it)
	}
	if ItemOf("**bold** text") != nil || ItemOf("-5 degrees") != nil || ItemOf("- [ ]").Mark != "" {
		t.Error("ItemOf negatives")
	}
	line := "see [P/#1.4 - zortex] and **b [L]**"
	spans := Inline(line, 0, len(line))
	if links := Links(spans); len(links) != 2 || links[1].Definition != "L" {
		t.Errorf("Links: %+v", links)
	}
	if got := SplitLines("\xef\xbb\xbfa\r\nb\n"); !reflect.DeepEqual(got, []string{"a", "b"}) {
		t.Errorf("SplitLines: %q", got)
	}
}

func BenchmarkParse(b *testing.B) {
	src, err := os.ReadFile(filepath.Join(fixtures, "syntax", "sample.zortex"))
	if err != nil {
		b.Fatal(err)
	}
	lines := SplitLines(string(src))
	b.SetBytes(int64(len(src)))
	for i := 0; i < b.N; i++ {
		Parse(lines, true)
	}
}
